    ['pending.sqlCheck','qabul_tasdiq.sql ishga tushirilganini tekshiring','Проверьте, выполнен ли qabul_tasdiq.sql','Check whether qabul_tasdiq.sql has been run','qabul_tasdiq.sql iske túsirilgenin tekseriń']
